    public static Optional<DeferredHolder<Item, ? extends Item>> getr(String id) {
        return ITEMS.getEntries().stream().filter(entry -> entry.getId().getPath().equals(id)).findFirst();
    }

    public static Optional<Item> get(String id) {
        return ItemRegistry.getr(id).map(DeferredHolder::get);
    }

    public static DeferredHolder<Item, ? extends Item> getrOrThrow(String id) {
        return ItemRegistry.getr(id).orElseThrow(() -> new IllegalArgumentException("No registered brimm item with name " + id));
    }

    public static Item getOrThrow(String id) {
        return ItemRegistry.get(id).orElseThrow(() -> new IllegalArgumentException("No registered brimm item with name " + id));
    }

