    private static <T extends Item> BiConsumer<DeferredHolder<Item, T>, String> addTabAndSetCraft(Collection<DeferredHolder<Item, ? extends Item>> tabHolder, ArmorItem.Type type, IngredientBuilder ... ingredients) {
        return ItemRegistry.addTabAndSetCraft(tabHolder, CraftSection.ofArmor(type), ingredients);
    }

    private static <T extends Item> BiConsumer<DeferredHolder<Item, T>, String> addTabAndSetCraft(Collection<DeferredHolder<Item, ? extends Item>> tabHolder, CraftSection section, IngredientBuilder ... ingredients) {
        return (obj, name) -> {
            tabHolder.add((DeferredHolder<Item, ? extends Item>)obj);
            if (ingredients.length > 0) {
                CraftBuilder craft = new CraftBuilder(() -> obj.get());
                for (IngredientBuilder ingredient : ingredients) {
                    craft.addIngredient(ingredient);
                }
                craft.setId(ResourceLocation.fromNamespaceAndPath("brimm", "wbcraft_" + name));
                CraftsManager.register(craft, section);
            } else {
                BrimmArmors.LOGGER.warn("Registering without workbench craft: " + obj.getKey().toString() + ".");
            }
        };
    }

