    private static Supplier<BrimmArmor> generateArmorSupplierHelmet(String unlocName, BrimmRarity rarity, RTSMatricesCompoundBuilder transform, float toughness, float knockbackResistance, int defenseValue, int durabilityValue, Collection<OverlayLocation> patchesPositions, Collection<IAmplifiableApplicableEffect> onWearEffects, Collection<MobEffect> preventOnWearEffects, Collection<?> auraEffects) {
        RTSMatricesCompound cmp = transform.build();
        int[] models = new int[]{SideSafeModelDeclarator.decleare(ModelDeclaration.ofArmor(unlocName, ArmorModelType.HELMET, true, cmp.get("ARMOR"), cmp.get("WORKBENCH")))};
        return ItemRegistry.generateArmorSupplier0(ArmorItem.Type.HELMET, unlocName, rarity, models, toughness, knockbackResistance, defenseValue, durabilityValue, patchesPositions, onWearEffects, preventOnWearEffects, auraEffects);
    }

