        return ItemRegistry.generateArmorSupplier0(ArmorItem.Type.BOOTS, unlocName, rarity, models, toughness, knockbackResistance, defenseValue, durabilityValue, ItemRegistry.nopatches(), onWearEffects, preventOnWearEffects, auraEffects);
