    private static Supplier<BrimmArmor> generateArmorSupplier0(ArmorItem.Type type, String unlocName, BrimmRarity rarity, int[] models, float toughness, float knockbackResistance, int defenseValue, int durabilityValue, Collection<OverlayLocation> patchesPositions, Collection<IAmplifiableApplicableEffect> onWearEffects, Collection<MobEffect> preventOnWearEffects, Collection<?> auraEffects) {
        ArmorConfig cfg = Optional.ofNullable(ConfigsManager.getAndEvict(unlocName)).orElse(ArmorConfig.EMPTY);
        SimpleArmorMaterial material = ConfigMergers.mergeBasicMaterial(unlocName, toughness, knockbackResistance, defenseValue, durabilityValue, type, cfg.materialOverrides());
        material.register();
        BrimmRarity mergedRarity = ConfigMergers.mergeRarity(rarity, cfg.rarityOverride());
        if (auraEffects != null && !auraEffects.isEmpty()) {
            throw new AssertionError((Object)"No longer supported");
        }
        ArmorEffectsSetup effects = new ArmorEffectsSetup(ReadonlySetView.of(onWearEffects.stream().map(oldInterface -> new ArmorEffectsSetup.AmplifiedEffect(oldInterface.effect(), oldInterface.amplifier())).collect(Collectors.toSet())), ReadonlySetView.of(new HashSet<MobEffect>(preventOnWearEffects)));
        return () -> new BrimmArmor(unlocName, type, mergedRarity, material, models, patchesPositions, effects);
    }

    private static <T extends Item> DeferredHolder<Item, T> registerItemAndExecute(BiConsumer<DeferredHolder<Item, T>, String> consumer, String name, Supplier<T> sup) {
        var registered = ITEMS.register(name, sup);
        consumer.accept(registered, name);
        return registered;
    }

    public static <T extends Item> DeferredHolder<Item, T> registerAndAddToMiscTab(String name, Supplier<T> sup) {
        var reg = ITEMS.register(name, sup);
        misc_tab_content.add((DeferredHolder<Item, ? extends Item>)reg);
        return reg;
    }

    public static void register(IEventBus eventBus) {
        SimpleArmorMaterial.MATERIALS.register(eventBus);
        ITEMS.register(eventBus);
        CREATIVE_TABS.register(eventBus);
    }
